documents.missing:
yamaa: '1.0'
type: spec
domain: TEST
keys: [ID]
input: {SRC: {path: input.csv, types: {ID: int, DV: float, AMT: int, VISIT: date}}}
output: {path: output.csv, columns: [ID, DV, AMT, VISIT, NOTE, BLANK], missing: MISSING}
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: DV, type: float, derivation: SRC.DV}
  - {name: AMT, type: int, derivation: SRC.AMT}
  - {name: VISIT, type: date, derivation: SRC.VISIT}
  - {name: NOTE, type: str, derivation: SRC.NOTE}
  - {name: BLANK, type: str, derivation: "''"}

documents.producer:
yamaa: "1.0"
type: spec
domain: PC
keys: [ID]
input: {RAW: {path: ../raw/raw.csv, types: {ID: int, DV: float}}}
columns:
  - {name: ID, type: int, label: Identifier, derivation: RAW.ID}
  - {name: DV, type: float, label: Dependent variable, derivation: RAW.DV}
output: {path: ../generated/pc.csv, columns: [ID, DV], missing: '.'}

documents.consumer:
yamaa: "1.0"
type: spec
domain: ROOT
keys: [ID]
input: {PC: {path: ../generated/pc.csv, schema: ../producer/p.yaml}}
columns:
  - {name: ID, type: int, label: Identifier, derivation: PC.ID}
output: {path: ../generated/root.csv, columns: [ID]}
